import json
import gurobipy as gp

# Data
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [20, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Model
m = gp.Model()

# Variables
x = {}
for i in range(2):
    for j in range(2):
        for p in range(2):
            x[i, j, p] = m.addVar(name=f'x_{i}_{j}_{p}', vtype=gp.GRB.INTEGER, lb=0)

# Constraints
for i in range(2):
    for p in range(2):
        m.addConstr(gp.quicksum(x[i, j, p] for j in range(2)) == supply[i][p], name=f'supply_{i}_{p}')
for j in range(2):
    for p in range(2):
        m.addConstr(gp.quicksum(x[i, j, p] for i in range(2)) == demand[p][j], name=f'demand_{p}_{j}')
for i in range(2):
    for j in range(2):
        m.addConstr(gp.quicksum(x[i, j, p] for p in range(2)) <= limit[i][j], name=f'limit_{i}_{j}')

# Objective
m.setObjective(gp.quicksum(cost[i][j][p] * x[i, j, p] for i in range(2) for j in range(2) for p in range(2)), sense=gp.GRB.MINIMIZE)

# Optimize
m.optimize()

# Output
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

