y_vars = {f"y_{i}_{j}_{k}_{l}": m.addVar(name=f"y_{i}_{j}_{k}_{l}", vtype=gp.GRB.BINARY) for i in range(5) for j in range(2) for k in range(5) for l in range(2) if (i, j) != (k, l)}
