    m.addConstr(start_vars[f"start_{i}_1"] - start_vars[f"start_{i}_0"] >= 2, name=f"c1_{i}")

for i in range(5):
    for j in range(2):
        for k in range(5):
            for l in range(2):
                if (i, j) != (k, l):
                    m.addConstr(start_vars[f"start_{i}_{j}"] - start_vars[f"start_{k}_{l}"] + 100000 * y_vars[f"y_{i}_{j}_{k}_{l}"] >= 1, name=f"c2_{i}_{j}_{k}_{l}")

for i in range(5):
    for j in range(2):
        m.addConstr(makespan - start_vars[f"start_{i}_{j}"] >= 1, name=f"c3_{i*2+j}")

# Objective
m.setObjective(makespan, gp.GRB.MINIMIZE)

# Optimize
m.optimize()

# Output
print(json.dumps({"objective_value": float(makespan.X), "assignment": {v.VarName: v.X for v in m.getVars()}}))

