import gurobipy as gp
from gurobipy import GRB

m = gp.Model()

# Variables
x = {}
s = {}
for j in range(5):
    for p in range(5):
        x[j, p] = m.addVar(vtype=GRB.BINARY, name=f'x_{j}_{p}')
        s[j, p] = m.addVar(vtype=GRB.INTEGER, lb=0, name=f's_{j}_{p}')

# Constraints
# Each job is assigned to exactly one position
for j in range(5):
    m.addConstr(gp.quicksum(x[j, p] for p in range(5)) == 1, name=f'c{j+1}')

# Each position is assigned exactly one job
for p in range(5):
    m.addConstr(gp.quicksum(x[j, p] for j in range(5)) == 1, name=f'c{p+6}')

# Start time constraints
processing_times = {
    (0, 0): 9, (0, 1): 7, (0, 2): 5, (0, 3): 6,
    (1, 0): 7, (1, 1): 10, (1, 2): 10, (1, 3): 8,
    (2, 0): 6, (2, 1): 9, (2, 2): 9, (2, 3): 8,
    (3, 0): 10, (3, 1): 10, (3, 2): 7, (3, 3): 8,
    (4, 0): 6, (4, 1): 10, (4, 2): 5, (4, 3): 10
}

for j in range(5):
    for p in range(1, 5):
        m.addConstr(s[j, p] - s[j, p-1] >= processing_times[j, p-1] * x[j, p-1], name=f'c{p+10}_{j}')

for j in range(5):
    for p in range(1, 5):
        m.addConstr(s[j, p] - s[j-1, 4] >= processing_times[j-1, 3] * x[j-1, 4], name=f'c{p+25}_{j}')

# Objective
m.setObjective(s[4, 4] + 6 * x[0, 4] + 8 * x[1, 4] + 8 * x[2, 4] + 8 * x[3, 4] + 10 * x[4, 4], GRB.MINIMIZE)

m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

