import json
import gurobipy as gp

m = gp.Model()

# Variables
produce = {}
startup = {}
quantity = {}
inventory = {}
backlog = {}

for p in range(3):
    for m in range(2):
        for t in range(3):
            produce[p, m, t] = m.addVar(vtype=gp.GRB.BINARY, name=f"produce_{p}_{m}_{t}")
            startup[p, m, t] = m.addVar(vtype=gp.GRB.BINARY, name=f"startup_{p}_{m}_{t}")
            quantity[p, m, t] = m.addVar(vtype=gp.GRB.CONTINUOUS, lb=0, name=f"quantity_{p}_{m}_{t}")

for p in range(3):
    for t in range(3):
        inventory[p, t] = m.addVar(vtype=gp.GRB.CONTINUOUS, lb=0, name=f"inventory_{p}_{t}")
        backlog[p, t] = m.addVar(vtype=gp.GRB.CONTINUOUS, lb=0, name=f"backlog_{p}_{t}")

# Constraints
for p in range(3):
    for t in range(3):
        m.addConstr(quantity[p, 0, t] + quantity[p, 1, t] + inventory[p, t] - backlog[p, t] == 
                    (21.53845915883999 if p == 0 and t == 0 else
                     22.99877365370049 if p == 0 and t == 1 else
                     20.41750946364395 if p == 0 and t == 2 else
                     24.34292430654904 if p == 1 and t == 0 else
                     18.69161579278047 if p == 1 and t == 1 else
                     16.96075239636408 if p == 1 and t == 2 else
                     15.44135005337596 if p == 2 and t == 0 else
                     24.75403844533352 if p == 2 and t == 1 else
                     17.09921582696376) + (inventory[p, t-1] if t > 0 else 0) - (backlog[p, t-1] if t > 0 else 0),
                    name=f"demand_{p}_{t}")

for m in range(2):
    for t in range(3):
        m.addConstr(quantity[0, m, t] + quantity[1, m, t] + quantity[2, m, t] + (6.900949355420833 if m == 0 else 7.255877688483005) * startup[0, m, t] <= 
                    (73.62985121550206 if m == 0 else 69.3191618930891),
                    name=f"capacity_{m}_{t}")

for m in range(2):
    for t in range(3):
        m.addConstr(produce[0, m, t] + produce[1, m, t] + produce[2, m, t] <= 1, name=f"single_product_{m}_{t}")

for p in range(3):
    for m in range(2):
        for t in range(3):
            m.addConstr(startup[p, m, t] - produce[p, m, t] >= 0, name=f"startup_{p}_{m}_{t}")
            if t > 0:
                m.addConstr(startup[p, m, t] - produce[p, m, t] + produce[p, m, t-1] >= 0, name=f"startup_{p}_{m}_{t}")

# Objective
m.setObjective(145.2319299071881 * sum(produce[p, m, t] for p in range(3) for m in range(2) for t in range(3)) +
               65.79360965435782 * sum(startup[p, m, t] for p in range(3) for m in range(2) for t in range(3)) +
               0.8652264753415143 * sum(inventory[0, t] for t in range(3)) +
               0.9341662877492469 * sum(inventory[1, t] for t in range(3)) +
               1.07339072521956 * sum(inventory[2, t] for t in range(3)) +
               7.607410261300208 * sum(backlog[0, t] for t in range(3)) +
               6.920344391340704 * sum(backlog[1, t] for t in range(3)) +
               6.497781941350707 * sum(backlog[2, t] for t in range(3)),
               gp.GRB.MINIMIZE)

m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

