import json
import gurobipy as gp

m = gp.Model()

# Variables
JobSchedule = {}
for j in range(6):
    for p in range(6):
        JobSchedule[j, p] = m.addVar(vtype=gp.GRB.BINARY, name=f"JobSchedule_{j}_{p}")

StartTime = {}
for j in range(6):
    for m in range(3):
        for p in range(6):
            StartTime[j, m, p] = m.addVar(vtype=gp.GRB.CONTINUOUS, lb=0, name=f"StartTime_{j}_{m}_{p}")

# Constraints
# One job per position
for p in range(6):
    m.addConstr(gp.quicksum(JobSchedule[j, p] for j in range(6)) == 1, name=f"one_job_per_position_{p}")

# One position per job
for j in range(6):
    m.addConstr(gp.quicksum(JobSchedule[j, p] for p in range(6)) == 1, name=f"one_position_per_job_{j}")

# Machine precedence
for j in range(6):
    for p in range(5):
        m.addConstr(StartTime[j, 1, p+1] >= StartTime[j, 0, p] + 5 * JobSchedule[j, p], name=f"machine_precedence_{j}_{p+1}")
        m.addConstr(StartTime[j, 2, p+1] >= StartTime[j, 1, p] + 5 * JobSchedule[j, p], name=f"machine_precedence_{j}_{p+1}")

# Job precedence
for j in range(6):
