import json
import gurobipy as gp
from gurobipy import GRB

m = gp.Model()

# Variables
x = {}
for d in ['D0', 'D1']:
    for u in ['U0', 'U1', 'U2', 'U3']:
        for s in ['S0', 'S1', 'S2']:
            x[f'x_{d}_{u}_{s}'] = m.addVar(name=f'x_{d}_{u}_{s}', lb=0, ub=GRB.INFINITY, vtype=GRB.CONTINUOUS)

y = {}
for d in ['D0', 'D1']:
    for u in ['U0', 'U1', 'U2', 'U3']:
        y[f'y_{d}_{u}'] = m.addVar(name=f'y_{d}_{u}', vtype=GRB.BINARY)

z = {}
for d in ['D0', 'D1']:
    z[f'z_{d}'] = m.addVar(name=f'z_{d}', lb=0, ub=20, vtype=GRB.INTEGER)

# Constraints
depot_supplies = {
    'D0': {'S0': 73.62, 'S1': 60.27, 'S2': 77.19},
    'D1': {'S0': 80.18, 'S1': 55.07, 'S2': 59.89}
}

unit_demands = {
    'U0': {'S0': 11.02, 'S1': 32.89, 'S2': 25.55},
    'U1': {'S0': 48.10, 'S1': 37.70, 'S2': 20.17},
    'U2': {'S0': 20.66, 'S1': 13.50, 'S2': 32.91},
    'U3': {'S0': 44.54, 'S1': 42.72, 'S2': 36.60}
}

for d in ['D0', 'D1']:
    for s in ['S0', 'S1', 'S2']:
        m.addConstr(gp.quicksum(x[f'x_{d}_{u}_{s}'] for u in ['U0', 'U1', 'U2', 'U3']) <= depot_supplies[d][s], name=f'depot_supply_{d}_{s}')

for u in ['U0', 'U1', 'U2', 'U3']:
    for s in ['S0', 'S1', 'S2']:
        m.addConstr(gp.quicksum(x[f'x_{d}_{u}_{s}'] for d in ['D0', 'D1']) >= unit_demands[u][s], name=f'unit_demand_{u}_{s}')

for d in ['D0', 'D1']:
    for u in ['U0', 'U1', 'U2', 'U3']:
        m.addConstr(gp.quicksum(x[f'x_{d}_{u}_{s}'] for s in ['S0', 'S1', 'S2']) <= 1000000000 * y[f'y_{d}_{u}'], name=f'route_activation_{d}_{u}')

for d in ['D0', 'D1']:
    m.addConstr(gp.quicksum(0.88 * x[f'x_{d}_{u}_{s}'] if s == 'S0' else 1.74 * x[f'x_{d}_{u}_{s}'] if s == 'S1' else 1.26 * x[f'x_{d}_{u}_{s}'] for u in ['U0', 'U1', 'U2', 'U3'] for s in ['S0', 'S1', 'S2']) <= 100 * z[f'z_{d}'], name=f'vehicle_capacity_{d}')

m.addConstr(gp.quicksum(z[f'z_{d}'] for d in ['D0', 'D1']) <= 20, name='total_vehicles')

# Objective
transport_costs = {
    'D0': {'U0': 1.43, 'U1': 2.41, 'U2': 1.33, 'U3': 4.30},
    'D1': {'U0': 1.54, 'U1': 2.32, 'U2': 3.99, 'U3': 4.16}
}

risk_costs = {
    'D0': {'U0': 171.19, 'U1': 54.39, 'U2': 81.82, 'U3': 155.95},
    'D1': {'U0': 89.85, 'U1': 88.95, 'U2': 102.78, 'U3': 133.38}
}

fleet_cost = 10.0

penalty_costs = {'S0': 80.9, 'S1': 57.4, 'S2': 96.19}

m.setObjective(
    gp.quicksum(transport_costs[d][u] * (x[f'x_{d}_{u}_S0'] + x[f'x_{d}_{u}_S1'] + x[f'x_{d}_{u}_S2']) for d in ['D0', 'D1'] for u in ['U0', 'U1', 'U2', 'U3']) +
    gp.quicksum(risk_costs[d][u] * y[f'y_{d}_{u}'] for d in ['D0', 'D1'] for u in ['U0', 'U1', 'U2', 'U3']) +
    gp.quicksum(fleet_cost * z[f'z_{d}'] for d in ['D0', 'D1']) +
    gp.quicksum(penalty_costs[s] * (unit_demands[u][s] - gp.quicksum(x[f'x_{d}_{u}_{s}'] for d in ['D0', 'D1'])) for u in ['U0', 'U1', 'U2', 'U3'] for s in ['S0', 'S1', 'S2']),
    GRB.MINIMIZE
)

m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

