            x[f"x_{d}_{u}_{s}"] = m.addVar(name=f"x_{d}_{u}_{s}", vtype=gp.GRB.INTEGER, lb=0, ub=depot_supplies[d][s])

# Define y variables
for d in ["D0", "D1", "D2"]:
    for u in ["U0", "U1", "U2"]:
        y[f"y_{d}_{u}"] = m.addVar(name=f"y_{d}_{u}", vtype=gp.GRB.BINARY, lb=0, ub=1)

# Add depot supply constraints
for d in ["D0", "D1", "D2"]:
    for s in ["S0", "S1", "S2"]:
        m.addConstr(gp.quicksum(x[f"x_{d}_{u}_{s}"] for u in ["U0", "U1", "U2"]) <= depot_supplies[d][s], name=f"depot_supply_{d}_{s}")

# Add unit demand constraints
for u in ["U0", "U1", "U2"]:
    for s in ["S0", "S1", "S2"]:
        m.addConstr(gp.quicksum(x[f"x_{d}_{u}_{s}"] for d in ["D0", "D1", "D2"]) >= unit_demands[u][s], name=f"unit_demand_{u}_{s}")

# Add route activation constraints
for d in ["D0", "D1", "D2"]:
    for u in ["U0", "U1", "U2"]:
        m.addConstr(gp.quicksum(x[f"x_{d}_{u}_{s}"] for s in ["S0", "S1", "S2"]) <= 100 * y[f"y_{d}_{u}"], name=f"route_activation_{d}_{u}")

# Add vehicle capacity constraints
for d in ["D0", "D1", "D2"]:
    for u in ["U0", "U1", "U2"]:
        m.addConstr(gp.quicksum(volume_per_supply[s] * x[f"x_{d}_{u}_{s}"] for s in ["S0", "S1", "S2"]) <= 100 * y[f"y_{d}_{u}"], name=f"vehicle_capacity_{d}_{u}")

# Add total vehicles constraint
m.addConstr(z <= 20, name="total_vehicles")

# Add route activation cost constraints
for d in ["D0", "D1", "D2"]:
    for u in ["U0", "U1", "U2"]:
        m.addConstr(y[f"y_{d}_{u}"] <= 1, name=f"route_activation_cost_{d}_{u}")

# Define objective
objective = gp.quicksum(
    transport_costs[d][u] * x[f"x_{d}_{u}_{s}"] for d in ["D0", "D1", "D2"] for u in ["U0", "U1", "U2"] for s in ["S0", "S1", "S2"]
) + gp.quicksum(
    10 * z
) + gp.quicksum(
    risk_costs[d][u] * y[f"y_{d}_{u}"] for d in ["D0", "D1", "D2"] for u in ["U0", "U1", "U2"]
) + gp.quicksum(
    penalty_costs[s] * (unit_demands[u][s] - gp.quicksum(x[f"x_{d}_{u}_{s}"] for d in ["D0", "D1", "D2"])) for u in ["U0", "U1", "U2"] for s in ["S0", "S1", "S2"]
)

m.setObjective(objective, gp.GRB.MINIMIZE)

# Optimize the model
m.optimize()

# Print the results
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

