    'C7': {'coords': (72, 47), 'demand': 9, 'time_window': [25, 110], 'service_time': 15},
    'C8': {'coords': (78, 72), 'demand': 17, 'time_window': [44, 111], 'service_time': 9},
    'C9': {'coords': (49, 32), 'demand': 12, 'time_window': [28, 92], 'service_time': 11},
