    'C12': {'coords': (26, 81), 'demand': 25, 'time_window': [47, 130], 'service_time': 9}
}
vehicle_capacity = 62
num_vehicles = 4
fixed_cost_per_vehicle = 100.0

# Calculate distances
def distance(p1, p2):
    return ((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)**0.5

# Create model
m = gp.Model()

# Variables
x = {}
t = {}
u = {}
for k in range(num_vehicles):
    u[k] = m.addVar(name=f'u_{k}', vtype=GRB.BINARY)
    for i in ['depot'] + list(customers.keys()):
        t[i, k] = m.addVar(name=f't_{i}_{k}', lb=0, ub=closing_time, vtype=GRB.CONTINUOUS)
        for j in ['depot'] + list(customers.keys()):
            if i != j:
                x[i, j, k] = m.addVar(name=f'x_{i}_{j}_{k}', vtype=GRB.BINARY)

# Constraints
# Each customer is visited exactly once
for i in customers.keys():
    m.addConstr(gp.quicksum(x[i, j, k] for j in ['depot'] + list(customers.keys()) for k in range(num_vehicles) if i != j) == 1, name=f'each_customer_once_{i}')

# Vehicle capacity
for k in range(num_vehicles):
    m.addConstr(gp.quicksum(customers[i]['demand'] * x[i, j, k] for i in customers.keys() for j in ['depot'] + list(customers.keys()) if i != j) <= vehicle_capacity, name=f'vehicle_capacity_{k}')

# Time windows
for i in customers.keys():
    for k in range(num_vehicles):
        m.addConstr(t[i, k] >= customers[i]['time_window'][0], name=f'time_window_early_{i}_{k}')
        m.addConstr(t[i, k] <= customers[i]['time_window'][1], name=f'time_window_late_{i}_{k}')

# Arrival time
for i in ['depot'] + list(customers.keys()):
    for j in ['depot'] + list(customers.keys()):
        if i != j:
            for k in range(num_vehicles):
                m.addConstr(t[i, k] + distance(customers[i]['coords'] if i != 'depot' else depot, customers[j]['coords'] if j != 'depot' else depot) + (customers[i]['service_time'] if i != 'depot' else 0) - t[j, k] <= (1 - x[i, j, k]) * closing_time, name=f'arrival_time_{i}_{j}_{k}')

