for k in range(num_vehicles):
    m.addConstr(gp.quicksum(x[i, j, k] for i in ['depot'] + list(customers.keys()) for j in ['depot'] + list(customers.keys()) if i != j) == u[k], name=f'vehicle_usage_{k}')

