import json
import gurobipy as gp

# Data
warehouses = ['S0', 'S1', 'S2', 'S3']
stores = ['D0', 'D1', 'D2', 'D3', 'D4', 'D5']
supply = {'S0': 222, 'S1': 122, 'S2': 153, 'S3': 182}
demand = {'D0': 47, 'D1': 51, 'D2': 29, 'D3': 58, 'D4': 32, 'D5': 49}
costs = {
    'S0': {'D0': 10.49, 'D1': 26.30, 'D2': 15.49, 'D3': 3.64, 'D4': 28.42, 'D5': 5.53},
    'S1': {'D0': 27.05, 'D1': 13.04, 'D2': 28.46, 'D3': 4.89, 'D4': 21.35, 'D5': 26.58},
    'S2': {'D0': 22.18, 'D1': 21.55, 'D2': 9.63, 'D3': 22.64, 'D4': 26.75, 'D5': 9.29},
    'S3': {'D0': 28.64, 'D1': 16.59, 'D2': 17.62, 'D3': 28.68, 'D4': 26.98, 'D5': 17.01}
}
emissions = {
    'S0': {'D0': 17.69, 'D1': 6.70, 'D2': 12.60, 'D3': 16.13, 'D4': 12.20, 'D5': 13.56},
    'S1': {'D0': 2.17, 'D1': 5.63, 'D2': 10.93, 'D3': 7.30, 'D4': 12.47, 'D5': 13.83},
    'S2': {'D0': 4.02, 'D1': 17.33, 'D2': 20.00, 'D3': 15.24, 'D4': 1.00, 'D5': 12.61},
    'S3': {'D0': 10.14, 'D1': 7.39, 'D2': 3.65, 'D3': 7.48, 'D4': 13.78, 'D5': 6.68}
}
setup_costs = {
    'S0': {'D0': 89, 'D1': 83, 'D2': 101, 'D3': 272, 'D4': 102, 'D5': 246},
    'S1': {'D0': 141, 'D1': 59, 'D2': 78, 'D3': 50, 'D4': 53, 'D5': 205},
    'S2': {'D0': 223, 'D1': 69, 'D2': 236, 'D3': 275, 'D4': 291, 'D5': 194},
    'S3': {'D0': 212, 'D1': 95, 'D2': 171, 'D3': 261, 'D4': 94, 'D5': 81}
}
min_order = {
    'S0': {'D0': 13, 'D1': 13, 'D2': 17, 'D3': 11, 'D4': 12, 'D5': 9},
    'S1': {'D0': 7, 'D1': 15, 'D2': 19, 'D3': 5, 'D4': 19, 'D5': 6},
    'S2': {'D0': 5, 'D1': 10, 'D2': 13, 'D3': 10, 'D4': 8, 'D5': 18},
    'S3': {'D0': 13, 'D1': 8, 'D2': 16, 'D3': 10, 'D4': 8, 'D5': 15}
}
max_suppliers = 3
cost_weight = 0.6
emissions_weight = 0.4

# Model
m = gp.Model()

# Variables
x = {}
y = {}
for w in warehouses:
    for s in stores:
        x[w, s] = m.addVar(name=f'x_{w}_{s}', vtype=gp.GRB.INTEGER, lb=0, ub=supply[w])
        y[w, s] = m.addVar(name=f'y_{w}_{s}', vtype=gp.GRB.BINARY)

# Constraints
# Supply constraints
for w in warehouses:
    m.addConstr(gp.quicksum(x[w, s] for s in stores) <= supply[w], name=f'supply_{w}')

# Demand constraints
for s in stores:
    m.addConstr(gp.quicksum(x[w, s] for w in warehouses) >= demand[s], name=f'demand_{s}')

# Minimum order constraints
for w in warehouses:
    for s in stores:
        m.addConstr(x[w, s] >= min_order[w][s] * y[w, s], name=f'min_order_{w}_{s}')

# Maximum suppliers per store
for s in stores:
    m.addConstr(gp.quicksum(y[w, s] for w in warehouses) <= max_suppliers, name=f'max_suppliers_{s}')

# Objective
m.setObjective(
    gp.quicksum(cost_weight * costs[w][s] * x[w, s] + emissions_weight * emissions[w][s] * x[w, s] + setup_costs[w][s] * y[w, s] for w in warehouses for s in stores),
    sense=gp.GRB.MINIMIZE
)

# Optimize
